# Bounded Source fixture with inspected actual yard-spot parameters. No map/source saves.
from pathlib import Path
import bpy,json,math,hashlib
from mathutils import Vector
out=Path('/tmp/cs-mine-front-spot-source-control-final14');assert not out.exists();out.mkdir();inventory=Path('/tmp/cs-mine-front-spots-source-final13.json');records=json.loads(inventory.read_text());source=records['spots'][0]
assert all(all(s[k]==source[k] for k in ['power','color','radius','spotSizeRadians','spotBlend','normalize','isSphere']) for s in records['spots']);assert source['normalize'] is True and source['isSphere'] is True
bpy.ops.wm.read_factory_settings(use_empty=True);scene=bpy.context.scene;scene.render.engine='CYCLES';scene.cycles.device='CPU';scene.cycles.samples=512;scene.cycles.seed=28361;scene.cycles.use_denoising=False;scene.render.use_persistent_data=False
scene.render.resolution_x=64;scene.render.resolution_y=64;scene.render.resolution_percentage=100;scene.render.pixel_aspect_x=1;scene.render.pixel_aspect_y=1;scene.render.film_transparent=False
world=bpy.data.worlds.new('Black control world');world.use_nodes=True;world.node_tree.nodes['Background'].inputs['Color'].default_value=(0,0,0,1);scene.world=world
bpy.ops.mesh.primitive_plane_add(size=.2);plane=bpy.context.object;material=bpy.data.materials.new('Lambert0.18');material.use_nodes=True;nt=material.node_tree;nt.nodes.clear();diffuse=nt.nodes.new('ShaderNodeBsdfDiffuse');diffuse.inputs['Color'].default_value=(.18,.18,.18,1);diffuse.inputs['Roughness'].default_value=0;output=nt.nodes.new('ShaderNodeOutputMaterial');nt.links.new(diffuse.outputs[0],output.inputs['Surface']);plane.data.materials.append(material)
data=bpy.data.lights.new('Actual Source yard spot fixture','SPOT');data.energy=source['power'];data.color=source['color'];data.shadow_soft_size=source['radius'];data.spot_size=source['spotSizeRadians'];data.spot_blend=source['spotBlend'];data.normalize=source['normalize'];data.use_soft_falloff=source['isSphere'];lamp=bpy.data.objects.new(data.name,data);scene.collection.objects.link(lamp)
cd=bpy.data.cameras.new('Fixture camera');cd.type='ORTHO';cd.ortho_scale=.08;cd.clip_start=.01;cd.clip_end=100;camera=bpy.data.objects.new(cd.name,cd);scene.collection.objects.link(camera);scene.camera=camera
scene.render.image_settings.media_type='IMAGE';scene.render.image_settings.file_format='OPEN_EXR';scene.render.image_settings.color_depth='32';scene.render.image_settings.color_mode='RGBA';scene.render.image_settings.exr_codec='ZIP'
frames=[]
for distance,angle in [(1,0),(2,0),(4,0),(4,30),(4,50),(4,60),(4,65),(4,75)]:
 a=math.radians(angle);direction=Vector((math.sin(a),0,-math.cos(a)));normal=-direction;plane.location=direction*distance;plane.rotation_euler=(0,-a,0);camera.location=plane.location+normal*.3;camera.rotation_euler=(-normal).to_track_quat('-Z','Y').to_euler();name=f'd{distance}-a{angle}';path=out/(name+'.exr');scene.render.filepath=str(path);bpy.context.view_layer.update();assert ((plane.matrix_world.to_3x3()@Vector((0,0,1))).normalized()-normal).length<1e-5;bpy.ops.render.render(write_still=True);frames.append({'name':name,'distance':distance,'angleDegrees':angle,'receiverPosition':list(plane.location),'receiverNormal':list(normal),'cameraPosition':list(camera.location),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
(out/'provenance.json').write_text(json.dumps({'status':'SourceSpotFixtureRenderedAwaitingFiniteAndNativeAudit','sourceInventorySha256':hashlib.sha256(inventory.read_bytes()).hexdigest(),'sourceSnapshotSha256':records['sourceSnapshotSha256'],'helperSha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'blenderVersion':bpy.app.version_string,'sourceParameters':source,'samples':512,'resolution':[64,64],'seed':28361,'frames':frames,'limits':['Numeric-data normalizedSpot parameterfamily; actual emitter nodes/exposure/temperature not yet certified; no full-map shade/cause/score','Sphericalradius.12 softens Source cone edge; receiverfaceslamp at each angle','No canonical/source scene saves']},indent=2)+'\n');print('CS_SOURCE_ACTUAL_SPOT_FIXTURE_OK',flush=True)
